import os
import re
from collections import defaultdict

REPO = "/bench/repo"

# Data layer: store package tree
def is_data_layer(path):
    rel = path.replace(REPO + "/", "")
    if rel.startswith("store/") or rel == "store":
        return True
    # proto store generated - separate, not our entity definitions
    if rel.startswith("proto/gen/store/"):
        return True
  if rel.startswith("proto/store/"):
        return True
    return False

# Entity types defined in store package (persistent entities, not Find/Update/Delete DTOs)
ENTITY_TYPES = {
    "Attachment", "IdentityProvider", "Inbox", "InstanceSetting",
    "Memo", "MemoRelation", "MemoShare", "Reaction",
    "User", "UserIdentity", "UserSetting",
    "AuthenticationConfigState",
}

def get_package_path(filepath):
    """Return Go package path from directory relative to module root."""
    rel = filepath.replace(REPO + "/", "")
    dirpath = os.path.dirname(rel)
    # Read package name from file
    with open(filepath) as f:
        for line in f:
            m = re.match(r'^package\s+(\w+)', line)
            if m:
                pkg_name = m.group(1)
                break
        else:
            pkg_name = "unknown"
    if dirpath:
        return dirpath.replace("/", ".")  # use directory as package path
    return pkg_name

def parse_imports(content):
    """Parse import block and return dict: local_name -> import_path"""
    imports = {}
    # Handle single import
    for m in re.finditer(r'import\s+"([^"]+)"', content):
        path = m.group(1)
        local = path.split("/")[-1]
        imports[local] = path
    # Handle import block
    block_match = re.search(r'import\s*\((.*?)\)', content, re.DOTALL)
    if block_match:
        block = block_match.group(1)
        for line in block.split('\n'):
            line = line.strip()
            if not line or line.startswith('//'):
                continue
            # alias "path"
            m = re.match(r'(\w+)\s+"([^"]+)"', line)
            if m:
                imports[m.group(1)] = m.group(2)
                continue
            m = re.match(r'"([^"]+)"', line)
            if m:
                path = m.group(1)
                local = path.split("/")[-1]
                imports[local] = path
    return imports

STORE_IMPORT_SUFFIX = "github.com/usememos/memos/store"

def find_store_alias(imports):
    for local, path in imports.items():
        if path == STORE_IMPORT_SUFFIX or path.endswith("/store"):
            return local
    return None

def find_type_refs(content, alias, types):
    """Find references to alias.TypeName"""
    refs = set()
    for t in types:
        # alias.TypeName - word boundary aware
        pattern = r'\b' + re.escape(alias) + r'\.' + re.escape(t) + r'\b'
        if re.search(pattern, content):
            refs.add(t)
    return refs

def analyze(include_tests=True):
    type_packages = defaultdict(set)  # type -> set of package paths
    type_files = defaultdict(lambda: defaultdict(set))  # type -> package -> files

    for root, dirs, files in os.walk(REPO):
        # skip vendor, .git
        dirs[:] = [d for d in dirs if d not in ('vendor', '.git', 'node_modules')]
        for fn in files:
            if not fn.endswith('.go'):
                continue
            if not include_tests and fn.endswith('_test.go'):
                continue
            filepath = os.path.join(root, fn)
            if is_data_layer(filepath):
                continue

            with open(filepath) as f:
                content = f.read()

            imports = parse_imports(content)
            alias = find_store_alias(imports)
            if not alias:
                continue

            refs = find_type_refs(content, alias, ENTITY_TYPES)
            if not refs:
                continue

            pkg_path = get_package_path(filepath)
            for t in refs:
                type_packages[t].add(pkg_path)
                type_files[t][pkg_path].add(filepath.replace(REPO + "/", ""))

    return type_packages, type_files

# Also check for references via other patterns (e.g. store package in same module without alias issues)
for label, include_tests in [("production", False), ("all", True)]:
    type_packages, type_files = analyze(include_tests)
    ranked = sorted(type_packages.items(), key=lambda x: (-len(x[1]), x[0]))
    print(f"\n=== {label.upper()} (exclude _test.go: {not include_tests}) ===")
    for t, pkgs in ranked[:15]:
        print(f"  {t}: {len(pkgs)} distinct packages")
    print("  --- TOP 2 ---")
    for t, pkgs in ranked[:2]:
        print(f"  {t}: {len(pkgs)} packages")
        for p in sorted(pkgs):
            files = sorted(type_files[t][p])
            print(f"    {p}: {files[:3]}{'...' if len(files)>3 else ''}")

PYEOF

