perl << 'PERL'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my $STORE_SUFFIX = "github.com/usememos/memos/store";

my %ENTITY_TYPES = map { $_ => 1 } qw(
    Attachment IdentityProvider Inbox InstanceSetting
    Memo MemoRelation MemoShare Reaction
    User UserIdentity UserSetting AuthenticationConfigState
);

sub is_data_layer {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    return 1 if $rel =~ /^store\//;
    return 1 if $rel =~ /^proto\/gen\/store\//;
    return 1 if $rel =~ /^proto\/store\//;
    return 0;
}

sub get_package_path {
    my ($filepath) = @_;
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;
    my $dir = dirname($rel);
    $dir =~ s/\//./g;
    return $dir eq '.' ? 'root' : $dir;
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $local = (split /\/, $path)[-1];
        $imports{$local} = $path;
    }
    if ($content =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next if !$line || $line =~ /^\/\//;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                my $local = (split /\/, $path)[-1];
                $imports{$local} = $path;
            }
        }
    }
    return %imports;
}

sub find_store_alias {
    my (%imports) = @_;
    for my $local (keys %imports) {
        my $path = $imports{$local};
        if ($path eq $STORE_SUFFIX || $path =~ /\/store$/) {
            return $local;
        }
    }
    return undef;
}

sub find_type_refs {
    my ($content, $alias, %types) = @_;
    my @refs;
    for my $t (keys %types) {
        my $pat = qr/\b\Q$alias\E\.\Q$t\E\b/;
        if ($content =~ $pat) {
            push @refs, $t;
        }
    }
    return @refs;
}

sub analyze {
    my ($include_tests) = @_;
    my %type_packages;
    my %type_files;

    find({
        wanted => sub {
            my $filepath = $File::Find::name;
            return unless $filepath =~ /\.go$/;
            return if !$include_tests && $filepath =~ /_test\.go$/;
            return if is_data_layer($filepath);

            open my $fh, '<', $filepath or return;
            my $content = do { local $/; <$fh> };
            close $fh;

            my %imports = parse_imports($content);
            my $alias = find_store_alias(%imports);
            return unless defined $alias;

            my @refs = find_type_refs($content, $alias, %ENTITY_TYPES);
            return unless @refs;

            my $pkg_path = get_package_path($filepath);
            my $rel = $filepath;
            $rel =~ s/^\Q$REPO\E\/?//;

            for my $t (@refs) {
                $type_packages{$t}{$pkg_path} = 1;
                $type_files{$t}{$pkg_path}{$rel} = 1;
            }
        },
        no_chdir => 1,
    }, $REPO);

    return (\%type_packages, \%type_files);
}

for my $label (['production', 0], ['all', 1]) {
    my ($name, $include_tests) = @$label;
    my ($type_packages, $type_files) = analyze($include_tests);

    my @ranked = sort {
        (scalar(keys %{$type_packages{$b}})) <=> (scalar(keys %{$type_packages{$a}}))
            || $a cmp $b
    } keys %type_packages;

    print "\n=== $name (exclude _test.go: " . ($include_tests ? "no" : "yes") . ") ===\n";
    for my $t (@ranked[0..14]) {
        my $n = scalar keys %{$type_packages->{$t}};
        print "  $t: $n distinct packages\n";
    }
    print "  --- TOP 2 ---\n";
    for my $t (@ranked[0..1]) {
        my $n = scalar keys %{$type_packages->{$t}};
        print "  $t: $n packages\n";
        for my $p (sort keys %{$type_files->{$t}}) {
            my @files = sort keys %{$type_files->{$t}{$p}};
            my $sample = join(", ", @files[0..2]);
            if (@files > 3) { $sample .= ", ..."; }
            print "    $p: $sample\n";
        }
    }
}
PERL

