#!/usr/bin/perl
use strict;
use warnings;

my $REPO = "/bench/repo";
my $STORE_PATH = "github.com/usememos/memos/store";

my %ENTITY_TYPES = map { $_ => 1 } qw(
    Attachment IdentityProvider Inbox InstanceSetting
    Memo MemoRelation MemoShare Reaction
    User UserIdentity UserSetting AuthenticationConfigState
);

sub is_data_layer {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    return 1 if $rel =~ /^store\//;
    return 1 if $rel =~ /^proto\/gen\/store\//;
    return 1 if $rel =~ /^proto\/store\//;
    return 0;
}

sub get_package_path {
    my ($filepath) = @_;
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;
    my $dir = $rel;
    $dir =~ s/\/[^\/]+$//;
    $dir =~ s/\//./g;
    return $dir eq '' ? 'root' : $dir;
}

sub last_path_segment {
    my ($path) = @_;
    my @parts = split('/', $path);
    return $parts[-1];
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        $imports{last_path_segment($path)} = $path;
    }
    while ($content =~ /import\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next if !$line || $line =~ /^\/\//;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                $imports{last_path_segment($path)} = $path;
            }
        }
    }
    return %imports;
}

sub find_store_alias {
    my (%imports) = @_;
    for my $local (keys %imports) {
        if ($imports{$local} eq $STORE_PATH) {
            return $local;
        }
    }
    return undef;
}

sub analyze_file {
    my ($filepath, $include_tests, $type_packages, $type_files) = @_;
    return if !$include_tests && $filepath =~ /_test\.go$/;
    return if is_data_layer($filepath);

    open my $fh, '<', $filepath or return;
    my $content = do { local $/; <$fh> };
    close $fh;

    my %imports = parse_imports($content);
    my $alias = find_store_alias(%imports);
    return unless defined $alias;

    my $pkg_path = get_package_path($filepath);
    my $rel = $filepath;
    $rel =~ s/^\Q$REPO\E\/?//;

    for my $t (keys %ENTITY_TYPES) {
        my $pat = qr/\b\Q$alias\E\.\Q$t\E\b/;
        if ($content =~ $pat) {
            $type_packages->{$t}{$pkg_path} = 1;
            $type_files->{$t}{$pkg_path}{$rel} = 1;
        }
    }
}

my $include_tests = ($ARGV[0] eq 'all') ? 1 : 0;
my %type_packages;
my %type_files;

while (my $filepath = <STDIN>) {
    chomp $filepath;
    analyze_file($filepath, $include_tests, \%type_packages, \%type_files);
}

my @ranked = sort {
    (scalar(keys %{$type_packages{$b}})) <=> (scalar(keys %{$type_packages{$a}}))
        || $a cmp $b
} keys %type_packages;

my $label = $include_tests ? 'all' : 'production';
print "=== $label ===\n";
for my $t (@ranked) {
    my $n = scalar keys %{$type_packages{$t}};
    print "$t: $n packages\n";
}
print "---TOP2 DETAIL---\n";
for my $t (@ranked[0..1]) {
    print "TYPE: $t (" . scalar(keys %{$type_packages{$t}}) . " packages)\n";
    for my $p (sort keys %{$type_files{$t}}) {
        my @files = sort keys %{$type_files{$t}{$p}};
        print "  PKG $p: @files\n";
    }
}
PERL

find /bench/repo -name "*.go" -type f | perl /tmp/analyze_refs.pl production
echo "========"
find /bench/repo -name "*.go" -type f | perl /tmp/analyze_refs.pl all

