#!/usr/bin/perl
use strict;
use warnings;
my $REPO = "/bench/repo";
my $STORE_PATH = "github.com/usememos/memos/store";

sub is_data_layer {
    my ($path) = @_;
    my $rel = $path; $rel =~ s/^\Q$REPO\E\/?//;
    return 1 if $rel =~ /^store\// || $rel =~ /^proto\/gen\/store\// || $rel =~ /^proto\/store\//;
    return 0;
}
sub get_package_path {
    my ($filepath) = @_;
    my $rel = $filepath; $rel =~ s/^\Q$REPO\E\/?//;
    my $dir = $rel; $dir =~ s/\/[^\/]+$//; $dir =~ s/\//./g;
    return $dir eq '' ? 'root' : $dir;
}
sub last_seg { my @p=split('/', $_[0]); $p[-1] }
sub parse_imports {
    my ($c) = @_; my %i;
    while ($c =~ /import\s+"([^"]+)"/g) { $i{last_seg($1)}=$1 }
    while ($c =~ /import\s*\((.*?)\)/gs) {
        for (split /\n/, $1) {
            s/^\s+|\s+$//g; next if !$_ || $_=~/^\/\//;
            if ($_ =~ /^(\w+)\s+"([^"]+)"/) { $i{$1}=$2 }
            elsif ($_ =~ /^"([^"]+)"/) { $i{last_seg($1)}=$1 }
        }
    }
    return %i;
}
my $include_tests = $ARGV[0] eq 'all';
my %counts;
while (<STDIN>) {
    chomp; my $fp=$_;
    next if !$include_tests && $fp=~/_test\.go$/;
    next if is_data_layer($fp);
    open my $fh,'<',$fp or next; my $c=do{local$/;<$fh>}; close $fh;
    my %imp=parse_imports($c);
    my $alias=undef; for (keys %imp) { if ($imp{$_} eq $STORE_PATH) { $alias=$_; last } }
    next unless $alias;
    while ($c =~ /\b\Q$alias\E\.([A-Z][A-Za-z0-9_]*)\b/g) {
        $counts{$1}{get_package_path($fp)}=1;
    }
}
my @ranked = sort { (scalar keys %{$counts{$b}}) <=> (scalar keys %{$counts{$a}}) || $a cmp $b } keys %counts;
for (@ranked[0..19]) {
    print "$_: " . scalar(keys %{$counts{$_}}) . " pkgs\n";
}
PERL
find /bench/repo -name "*.go" -type f | perl /tmp/analyze_all_types.pl production

